const body = $json.body || {};

const token = String(body.token || '').trim();
const motif = String(body.motif || '').trim();

if (!/^[0-9a-fA-F-]{36}$/.test(token)) {
  throw new Error('Token de gestion invalide');
}

if (motif.length > 500) {
  throw new Error('Motif trop long');
}

return [{
  json: {
    token,
    motif: motif || null
  }
}];

const item = $json || {};

if (!item.reference) {
  return [{
    json: {
      success: false,
      cancelled: false,
      message: 'Rendez-vous introuvable ou déjà annulé'
    }
  }];
}

return [{
  json: {
    success: true,
    cancelled: true,
    appointment: {
      reference: item.reference,
      statut: item.statut,
      cancelled_at: item.cancelled_at
    },
    slot: {
      capacite: item.capacite,
      places_reservees: item.places_reservees,
      places_disponibles: item.places_disponibles
    }
  }
}];
